import numpy as np

d1_in = np.array([list(map(int, line.split())) for line in d1_in_str.strip().split('\n')])
d1_out = np.array([list(map(int, line.split())) for line in d1_out_str.strip().split('\n')])

# Let me reconsider - maybe the check is: is the cell "between" two diagonals?
# Or: are there source 2s on BOTH the main AND anti-diagonal passing through?

# Actually, let me look at whether we're attenuating - not all diagonals are filled
# Let me check which directions from source are COMPLETELY filled vs PARTIAL

source_2s = np.argwhere(d1_in == 2)

def check_ray_direction(src_r, src_c, r, c):
    """What direction is (r,c) from source (src_r, src_c)?"""
    dr = r - src_r
    dc = c - src_c

    if dr < 0 and dc < 0:
        return "up-left"
    elif dr < 0 and dc > 0:
        return "up-right"
    elif dr > 0 and dc < 0:
        return "down-left"
    elif dr > 0 and dc > 0:
        return "down-right"
    else:
        return "same"

# Group new 2s by direction from each source
for sr_idx, (sr, sc) in enumerate(source_2s):
    up_lr_count = 0
    up_rr_count = 0
    dl_count = 0
    dr_count = 0

    for r in range(d1_in.shape[0]):
        for c in range(d1_in.shape[1]):
            if d1_out[r, c] == 2:
                if r == sr and c == sc:
                    continue
                direction = check_ray_direction(sr, sc, r, c)
                if direction == "up-left":
                    up_lr_count += 1
                elif direction == "up-right":
                    up_rr_count += 1
                elif direction == "down-left":
                    dl_count += 1
                elif direction == "down-right":
                    dr_count += 1

    print(f"Source {sr},{sc}: up-left={up_lr_count}, up-right={up_rr_count}, down-left={dl_count}, down-right={dr_count}")

