# Use the diagonal alignment rule: any 0 on same main or anti-diagonal as a source becomes 8
def is_on_diagonal_from_sources(r, c, sources):
    for sr, sc in sources:
        # Main diagonal: r - c constant
        if r - c == sr - sc:
            return True
        # Anti-diagonal: r + c constant  
        if r + c == sr + sc:
            return True
    return False

for r in range(test_in.shape[0]):
    for c in range(test_in.shape[1]):
        if test_in[r, c] == 0:
            if is_on_diagonal_from_sources(r, c, source_eights):
                output[r, c] = 8

